{"content":"// Package cli parses the command line of the frob tool.
package cli

import (
	"errors"
	"fmt"
	"strconv"
)

// ErrUsage is wrapped by every parse error.
var ErrUsage = errors.New("usage error")

// Config is the parsed command line.
type Config struct {
	Verbose bool
	Count   int
	Output  string
	Tags    []string
	Args    []string
}

// Parse parses the command line arguments.
func Parse(args []string) (Config, error) {
	cfg := Config{Count: 1, Output: "-"}

	// valueOpts maps a long/short name to the setter.
	setCount := func(v string) error {
		n, err := strconv.Atoi(v)
		if err != nil {
			return fmt.Errorf("flag -n: invalid value %q: not an integer: %w", v, ErrUsage)
		}
		if n < 0 {
			return fmt.Errorf("flag -n: invalid value %q: must be >= 0: %w", v, ErrUsage)
		}
		cfg.Count = n
		return nil
	}
	setOutput := func(v string) { cfg.Output = v }
	setTag := func(v string) { cfg.Tags = append(cfg.Tags, v) }

	needValue := func(name string, args []string) (string, []string, error) {
		if len(args) == 0 {
			return "", args, fmt.Errorf("flag %s: missing value: %w", name, ErrUsage)
		}
		return args[0], args[1:], nil
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]

		// A lone "-" is a positional argument; "--" ends option parsing.
		if arg == "-" {
			cfg.Args = append(cfg.Args, arg)
			continue
		}
		if arg == "--" {
			cfg.Args = append(cfg.Args, args[i+1:]...)
			break
		}
		if arg[0] != '-' {
			cfg.Args = append(cfg.Args, arg)
			continue
		}

		if len(arg) == 2 {
			return cfg, fmt.Errorf("unknown flag %s: %w", arg, ErrUsage)
		}

		if arg[1] == '-' { // long flag
			name, value, hasValue := arg[2:], "", false
			if eq := indexByte(name, '='); eq >= 0 {
				name, value, hasValue = name[:eq], name[eq+1:], true
			}
			switch name {
			case "verbose":
				if hasValue {
					return cfg, fmt.Errorf("flag --verbose: unexpected value %q: %w", value, ErrUsage)
				}
				cfg.Verbose = true
			case "count":
				if !hasValue {
					v, rest, err := needValue("--count", args[i+1:])
					if err != nil {
						return cfg, err
					}
					value = v
					i = i + len(rest) - 1 + 1 // advance past the value
					i--                        // the loop will increment
				}
				if err := setCount(value); err != nil {
					return cfg, err
				}
			case "output":
				if !hasValue {
					v, rest, err := needValue("--output", args[i+1:])
					if err != nil {
						return cfg, err
					}
					value = v
					i = i + len(rest) - 1 + 1
					i--
				}
				setOutput(value)
			case "tag":
				if !hasValue {
					v, rest, err := needValue("--tag", args[i+1:])
					if err != nil {
						return cfg, err
					}
					value = v
					i = i + len(rest) - 1 + 1
					i--
				}
				setTag(value)
			default:
				return cfg, fmt.Errorf("unknown flag --%s: %w", name, ErrUsage)
			}
			continue
		}

		// Short flag cluster, e.g. -vv or -n5.
		cluster := arg[1:]
		for j := 0; j < len(cluster); j++ {
			switch cluster[j] {
			case 'v':
				cfg.Verbose = true
			case 'n', 'o':
				longName := "output"
				if cluster[j] == 'n' {
					longName = "count"
				}
				name := "-" + string(cluster[j])
				var value string
				if j+1 < len(cluster) { // -n5 / -o=foo style tail
					value = cluster[j+1:]
					j = len(cluster) // consume the rest of the cluster
				} else {
					rest := args[i+1:]
					v, r, err := needValue(name, rest)
					if err != nil {
						return cfg, err
					}
					value = v
					i += len(rest) - len(r)
				}
				if longName == "count" {
					if err := setCount(value); err != nil {
						return cfg, err
					}
				} else {
					setOutput(value)
				}
			default:
				return cfg, fmt.Errorf("unknown flag -%c: %w", cluster[j], ErrUsage)
			}
		}
	}

	return cfg, nil
}

func indexByte(s string, c byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			return i
		}
	}
	return -1
}
