{"content":"package cli

import (
	"errors"
	"strings"
	"testing"
)

func TestTmpRules(t *testing.T) {
	ok := func(args ...string) Config {
		t.Helper()
		c, err := Parse(args)
		if err != nil {
			t.Fatalf("Parse(%v): %v", args, err)
		}
		return c
	}
	bad := func(msg string, args ...string) {
		t.Helper()
		_, err := Parse(args)
		if err == nil || !errors.Is(err, ErrUsage) || !strings.Contains(err.Error(), msg) {
			t.Fatalf("Parse(%v) = %v; want usage error mentioning %q", args, err, msg)
		}
	}

	c := ok("-v", "-v")
	if !c.Verbose {
		t.Errorf("vv")
	}
	c = ok("-vv")
	if !c.Verbose {
		t.Errorf("-vv")
	}
	c = ok("--verbose", "--count", "5", "--count=6")
	if !c.Verbose || c.Count != 6 {
		t.Errorf("%+v", c)
	}
	c = ok("-n", "3")
	if c.Count != 3 {
		t.Errorf("%+v", c)
	}
	c = ok("-n=4")
	if c.Count != 4 {
		t.Errorf("%+v", c)
	}
	c = ok("-o", "f.txt")
	if c.Output != "f.txt" {
		t.Errorf("%+v", c)
	}
	c = ok("--output=out.bin")
	if c.Output != "out.bin" {
		t.Errorf("%+v", c)
	}
	c = ok("--tag", "a", "--tag=b")
	if len(c.Tags) != 2 || c.Tags[0] != "a" || c.Tags[1] != "b" {
		t.Errorf("%+v", c)
	}
	c = ok("x", "y")
	if len(c.Args) != 2 || c.Args[0] != "x" {
		t.Errorf("%+v", c)
	}
	if c.Tags != nil {
		t.Errorf("tags nil: %+v", c)
	}
	c = ok("--", "-v", "-x")
	if len(c.Args) != 2 || c.Args[0] != "-v" || c.Args[1] != "-x" || c.Verbose {
		t.Errorf("%+v", c)
	}
	c = ok("-", "-v")
	if len(c.Args) != 1 || c.Args[0] != "-" || !c.Verbose {
		t.Errorf("%+v", c)
	}
	c = ok("a", "--", "b")
	if len(c.Args) != 2 || c.Args[0] != "a" || c.Args[1] != "b" {
		t.Errorf("%+v", c)
	}

	bad("-n", "-n")
	bad("-n", "-n", "abc")
	bad("-n", "-n", "-1")
	bad("--count", "--count")
	bad("--count", "--count", "-3")
	bad("-o", "-o")
	bad("--output", "--output")
	bad("-x", "-x")
	bad("--nope", "--nope")
	bad("-q", "-q")
	bad("-x", "--", "-x") // after -- it's positional, not an error
}
