   79						v, consume, err := takeValue("--output", args[i+1:], i)
   80						if err != nil {
   81							return cfg, err
   82						}
   83						value, i = v, i+consume
   84					}
   85					cfg.Output = value
   86				case "tag":
   87					if !hasValue {
   88						v, consume, err := takeValue("--tag", args[i+1:], i)
   89						if err != nil {
   90							return cfg, err
   91						}
   92						value, i = v, i+consume
   93					}
   94					cfg.Tags = append(cfg.Tags, value)
   95				default:
   96					return cfg, fmt.Errorf("unknown flag --%s: %w", name, ErrUsage)
   97				}
   98				continue
   99			}
  100	
  101			// Short flag cluster, e.g. -vv or -n5.
  102			cluster := arg[1:]
  103			for j := 0; j < len(cluster); j++ {
  104				switch c := cluster[j]; c {
  105				case 'v':
  106					cfg.Verbose = true
  107				case 'n', 'o':
  108					longName := "-n"
  109					if c == 'o' {
  110						longName = "-o"
  111					}
  112					var value string
  113					if j+1 < len(cluster) { // e.g. -n5 or -n=5
  114						value = strings.TrimPrefix(cluster[j+1:], "=")
  115						j = len(cluster) // consume the rest of the cluster
  116					} else {
  117						v, consume, err := takeValue(longName, args[i+1:], i)
  118						if err != nil {
  119							return cfg, err
  120						}
  121						value, i = v, i+consume
  122					}
  123					if c == 'n' {
  124						if err := setCount(arg, value); err != nil {
  125							return cfg, err
  126						}
  127					} else {
  128						cfg.Output = value
  129					}
  130				default:
  131					return cfg, fmt.Errorf("unknown flag -%c: %w", c, ErrUsage)
  132				}
  133			}
  134		}
  135	
  136		return cfg, nil
  137	}
  138	
  139	// takeValue returns the first element of rest (an error if rest is empty).
  140	func takeValue(name string, rest []string, i int) (string, int, error) {
  141		if len(rest) == 0 {
  142			return "", 0, fmt.Errorf("flag %s: missing value: %w", name, ErrUsage)
  143		}
  144		return rest[0], 1, nil
  145	}
